python3 - <<'PY'
import os, json, sys
content = open('.env.test').read().splitlines()
obj = {}
for line in content:
    if not line.strip() or line.strip().startswith('#'):
        continue
    if '=' in line:
        k,v = line.split('=',1)
        obj[k]=v
print(json.dumps(obj))
