import os, json, sys
env = {}
with open('.env.test') as f:
    for line in f:
        line=line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            k,v=line.split('=',1)
            env[k]=v
print(json.dumps(env))
